"use strict";!function(a){a.behaviors.dxprThemeActiveTrail={attach:function(a){if(a===document){var t=window.location.pathname,i=window.location.origin;document.querySelectorAll("#dxpr-theme-main-menu .navbar-nav a[href]").forEach(function(a){var e=a.getAttribute("href");if(e&&!e.startsWith("#")){var r=new URL(a.href,i);if(r.origin===i&&r.pathname===t){a.classList.add("is-active");for(var n=a.closest("li");n;){n.classList.add("menu-item--active-trail"),n.classList.add("active");var c=n.parentElement;if(!c)break;n=c.closest("li")}}}})}}}}(Drupal);